'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['prismVolume']);
const { prismVolume } = api;
assert.equal(typeof prismVolume, 'function');

assert.equal(prismVolume(2, 3, 4), 24);
assert.equal(prismVolume(1.5, 2, 3), 9);
assert.equal(prismVolume(0, 8, 9), 0);
assert.equal(prismVolume(8, 0, 9), 0);
assert.equal(prismVolume(8, 9, 0), 0);
assert.equal(prismVolume(Number.MIN_VALUE, 1, 1), Number.MIN_VALUE);
assert.equal(prismVolume(2, 3, 4), 24);

for (const args of [
  ['2', 3, 4], [2, null, 4], [2, 3, undefined],
  [NaN, 3, 4], [2, Infinity, 4], [2, 3, -Infinity],
  [{}, 3, 4], [2, [], 4]
]) assert.throws(() => prismVolume(...args), TypeError);

for (const args of [[-1, 2, 3], [1, -2, 3], [1, 2, -3]]) {
  assert.throws(() => prismVolume(...args), RangeError);
}

